    minInstanceNumber: 0,
    maxInstanceNumber: 10,
    vpcId: vpcId,
    networks: [{
        id: subnetId,
    }],
    lbaasListeners: [{
        poolId: pool1.id,
        protocolPort: listener1.protocolPort,
    }],
});
