    flavorId: myflavor.then(myflavor => myflavor.ids?.[0]),
    securityGroupIds: [secgroupId],
    availabilityZone: myaz.then(myaz => myaz.names?.[0]),
    networks: [{
        uuid: mynet.then(mynet => mynet.id),
    }],
});
