const config = new pulumi.Config();
const vpcId = config.requireObject<any>("vpcId");
const subnetId = config.requireObject<any>("subnetId");
const securityGroupId = config.requireObject<any>("securityGroupId");
const accessPassword = config.requireObject<any>("accessPassword");
const availabilityZones = config.getObject<any>("availabilityZones") || [
    "your_availability_zones_a",
    "your_availability_zones_b",
    "your_availability_zones_c",
];
const flavorId = config.get("flavorId") || "your_flavor_id, such: c6.2u4g.cluster";
const storageSpecCode = config.get("storageSpecCode") || "your_storage_spec_code, such: dms.physical.storage.ultra.v2";
// Query flavor information based on flavorID and storage I/O specification.
// Make sure the flavors are available in the availability zone.
const test = sbercloud.getDmsKafkaFlavors({
    type: "cluster",
    flavorId: flavorId,
    availabilityZones: availabilityZones,
    storageSpecCode: storageSpecCode,
});
const testDmsKafkaInstance = new sbercloud.DmsKafkaInstance("test", {
    name: "kafka_test",
    vpcId: vpcId,
    networkId: subnetId,
    securityGroupId: securityGroupId,
    flavorId: test.then(test => test.flavorId),
    storageSpecCode: test.then(test => test.flavors?.[0]?.ios?.[0]?.storageSpecCode),
    availabilityZones: availabilityZones,
    engineVersion: "2.7",
    storageSpace: 600,
    brokerNum: 3,
    sslEnable: true,
    accessUser: "user",
    password: accessPassword,
    parameters: [{
        name: "min.insync.replicas",
        value: "2",
    }],
});
