    functionUrn: functionUrn,
    maxAsyncEventAgeInSeconds: 3500,
    maxAsyncRetryAttempts: 2,
    enableAsyncStatusLog: true,
    onSuccess: {
        destination: "OBS",
        param: JSON.stringify({
