import com.pulumi.sbercloud.SbercloudFunctions;
import com.pulumi.sbercloud.inputs.GetAvailabilityZonesArgs;
import com.pulumi.sbercloud.MapreduceCluster;
import com.pulumi.sbercloud.MapreduceClusterArgs;
import com.pulumi.sbercloud.inputs.MapreduceClusterMasterNodesArgs;
import com.pulumi.sbercloud.inputs.MapreduceClusterAnalysisCoreNodesArgs;
import com.pulumi.sbercloud.inputs.MapreduceClusterAnalysisTaskNodesArgs;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Map;
import java.io.File;
import java.nio.file.Files;
import java.nio.file.Paths;

public class App {
    public static void main(String[] args) {
        Pulumi.run(App::stack);
    }

    public static void stack(Context ctx) {
        final var config = ctx.config();
        final var test = SbercloudFunctions.getAvailabilityZones(GetAvailabilityZonesArgs.builder()
            .build());

        final var clusterName = config.require("clusterName");
        final var password = config.require("password");
        final var vpcId = config.require("vpcId");
        final var subnetId = config.require("subnetId");
        var testMapreduceCluster = new MapreduceCluster("testMapreduceCluster", MapreduceClusterArgs.builder()
            .availabilityZone(test.names()[0])
            .name(clusterName)
            .version("MRS 2.1.0")
            .type("ANALYSIS")
            .componentLists(            
                "Hadoop",
                "Hive",
                "Tez")
            .managerAdminPass(password)
            .nodeAdminPass(password)
            .vpcId(vpcId)
            .subnetId(subnetId)
            .masterNodes(MapreduceClusterMasterNodesArgs.builder()
                .flavor("c6.2xlarge.4.linux.bigdata")
                .nodeNumber(2)
                .rootVolumeType("SAS")
                .rootVolumeSize(300)
                .dataVolumeType("SAS")
                .dataVolumeSize(480)
                .dataVolumeCount(1)
                .build())
            .analysisCoreNodes(MapreduceClusterAnalysisCoreNodesArgs.builder()
                .flavor("c6.2xlarge.4.linux.bigdata")
                .nodeNumber(2)
                .rootVolumeType("SAS")
                .rootVolumeSize(300)
                .dataVolumeType("SAS")
                .dataVolumeSize(480)
                .dataVolumeCount(1)
                .build())
            .analysisTaskNodes(MapreduceClusterAnalysisTaskNodesArgs.builder()
                .flavor("c6.2xlarge.4.linux.bigdata")
                .nodeNumber(1)
                .rootVolumeType("SAS")
                .rootVolumeSize(300)
                .dataVolumeType("SAS")
                .dataVolumeSize(480)
                .dataVolumeCount(1)
                .build())
            .tags(Map.ofEntries(
                Map.entry("foo", "bar"),
                Map.entry("key", "value")
            ))
            .build());

    }
}
