package main

import (
	"github.com/pulumi/pulumi/sdk/v3/go/pulumi"
	"github.com/pulumi/pulumi/sdk/v3/go/pulumi/config"
	"github.com/simple-container-com/pulumi-sbercloud/sdk/go/sbercloud"
)

func main() {
	pulumi.Run(func(ctx *pulumi.Context) error {
		test, err := sbercloud.GetAvailabilityZones(ctx, &sbercloud.GetAvailabilityZonesArgs{}, nil)
		if err != nil {
			return err
		}
		cfg := config.New(ctx, "")
		var clusterName interface{}
		cfg.RequireObject("clusterName", &clusterName)
		var password interface{}
		cfg.RequireObject("password", &password)
		var vpcId interface{}
		cfg.RequireObject("vpcId", &vpcId)
		var subnetId interface{}
		cfg.RequireObject("subnetId", &subnetId)
		_, err = sbercloud.NewMapreduceCluster(ctx, "test", &sbercloud.MapreduceClusterArgs{
			AvailabilityZone: pulumi.String(test.Names[0]),
			Name:             pulumi.Any(clusterName),
			Type:             pulumi.String("STREAMING"),
			Version:          pulumi.String("MRS 2.1.0"),
			ManagerAdminPass: pulumi.Any(password),
			NodeAdminPass:    pulumi.Any(password),
			VpcId:            pulumi.Any(vpcId),
			SubnetId:         pulumi.Any(subnetId),
			ComponentLists: pulumi.StringArray{
				pulumi.String("Storm"),
			},
			MasterNodes: &sbercloud.MapreduceClusterMasterNodesArgs{
				Flavor:          pulumi.String("c6.2xlarge.4.linux.bigdata"),
				NodeNumber:      pulumi.Int(2),
				RootVolumeType:  pulumi.String("SAS"),
				RootVolumeSize:  pulumi.Int(300),
				DataVolumeType:  pulumi.String("SAS"),
				DataVolumeSize:  pulumi.Int(480),
				DataVolumeCount: pulumi.Int(1),
			},
			StreamingCoreNodes: &sbercloud.MapreduceClusterStreamingCoreNodesArgs{
				Flavor:          pulumi.String("c6.2xlarge.4.linux.bigdata"),
				NodeNumber:      pulumi.Int(2),
				RootVolumeType:  pulumi.String("SAS"),
				RootVolumeSize:  pulumi.Int(300),
				DataVolumeType:  pulumi.String("SAS"),
				DataVolumeSize:  pulumi.Int(480),
				DataVolumeCount: pulumi.Int(1),
			},
			Tags: pulumi.StringMap{
				"foo": pulumi.String("bar"),
				"key": pulumi.String("value"),
			},
		})
		if err != nil {
			return err
		}
		return nil
	})
}
