sbercloud:index/networkAcl:NetworkAcl.description:
Manages a network ACL resource within SberCloud.

## Example Usage

<!--Start PulumiCodeChooser -->
```typescript
import * as pulumi from "@pulumi/pulumi";
import * as sbercloud from "@pulumi/sbercloud";

const subnet = sbercloud.getVpcSubnet({
    name: "subnet-default",
});
const rule1 = new sbercloud.NetworkAclRule("rule_1", {
    name: "my-rule-1",
    description: "drop TELNET traffic",
    action: "deny",
    protocol: "tcp",
    destinationPort: "23",
    enabled: true,
});
const rule2 = new sbercloud.NetworkAclRule("rule_2", {
    name: "my-rule-2",
    description: "drop NTP traffic",
    action: "deny",
    protocol: "udp",
    destinationPort: "123",
    enabled: false,
});
const fwAcl = new sbercloud.NetworkAcl("fw_acl", {
    name: "my-fw-acl",
    subnets: [subnet.then(subnet => subnet.id)],
    inboundRules: [
        rule1.id,
        rule2.id,
    ],
});
```
