```
```csharp
using System.Collections.Generic;
using System.Linq;
using Pulumi;
using Sbercloud = Pulumi.Sbercloud;

return await Deployment.RunAsync(() => 
{
    var subnet = Sbercloud.GetVpcSubnet.Invoke(new()
    {
        Name = "subnet-default",
    });

    var rule1 = new Sbercloud.NetworkAclRule("rule_1", new()
    {
        Name = "my-rule-1",
        Description = "drop TELNET traffic",
        Action = "deny",
        Protocol = "tcp",
        DestinationPort = "23",
        Enabled = true,
    });

    var rule2 = new Sbercloud.NetworkAclRule("rule_2", new()
    {
        Name = "my-rule-2",
        Description = "drop NTP traffic",
        Action = "deny",
        Protocol = "udp",
        DestinationPort = "123",
        Enabled = false,
    });

    var fwAcl = new Sbercloud.NetworkAcl("fw_acl", new()
    {
        Name = "my-fw-acl",
        Subnets = new[]
        {
