Provides an VPC subnet resource.

## Example Usage

<!--Start PulumiCodeChooser -->
```typescript
import * as pulumi from "@pulumi/pulumi";
import * as sbercloud from "@pulumi/sbercloud";

const config = new pulumi.Config();
const vpcName = config.requireObject<any>("vpcName");
const vpcCidr = config.requireObject<any>("vpcCidr");
const subnetName = config.requireObject<any>("subnetName");
const subnetCidr = config.requireObject<any>("subnetCidr");
const subnetGatewayIp = config.requireObject<any>("subnetGatewayIp");
const availabilityZone = config.requireObject<any>("availabilityZone");
const vpc = new sbercloud.Vpc("vpc", {
    name: vpcName,
    cidr: vpcCidr,
});
const subnet = new sbercloud.VpcSubnet("subnet", {
    name: subnetName,
    cidr: subnetCidr,
    gatewayIp: subnetGatewayIp,
    vpcId: vpc.id,
    availabilityZone: availabilityZone,
});
const subnetWithTags = new sbercloud.VpcSubnet("subnet_with_tags", {
    name: subnetName,
    cidr: subnetCidr,
    gatewayIp: subnetGatewayIp,
    vpcId: vpc.id,
    availabilityZone: availabilityZone,
    tags: {
        foo: "bar",
        key: "value",
    },
});
const subnetWithDhcp = new sbercloud.VpcSubnet("subnet_with_dhcp", {
    name: subnetName,
    cidr: subnetCidr,
    gatewayIp: subnetGatewayIp,
    vpcId: vpc.id,
    availabilityZone: availabilityZone,
    dhcpLeaseTime: "24h",
    dhcpIpv6LeaseTime: "4h",
    ntpServerAddress: "10.100.0.33,10.100.0.34",
    dhcpDomainName: "test.domainnanme",
});
