## Example Usage

<!--Start PulumiCodeChooser -->
```typescript
import * as pulumi from "@pulumi/pulumi";
import * as sbercloud from "@pulumi/sbercloud";

const flavors = sbercloud.getElbFlavors({
    type: "L7",
    maxConnections: 200000,
    cps: 2000,
    bandwidth: 50,
});
// Create Dedicated Load Balancer with the first matched flavor
const lb = new sbercloud.ElbLoadbalancer("lb", {l7FlavorId: flavors.then(flavors => flavors.ids?.[0])});
```
```python
import pulumi
import pulumi_sbercloud as sbercloud

flavors = sbercloud.get_elb_flavors(type="L7",
    max_connections=200000,
    cps=2000,
    bandwidth=50)
# Create Dedicated Load Balancer with the first matched flavor
lb = sbercloud.ElbLoadbalancer("lb", l7_flavor_id=flavors.ids[0])
```
```csharp
using System.Collections.Generic;
using System.Linq;
using Pulumi;
using Sbercloud = Pulumi.Sbercloud;

return await Deployment.RunAsync(() => 
{
    var flavors = Sbercloud.GetElbFlavors.Invoke(new()
    {
        Type = "L7",
        MaxConnections = 200000,
        Cps = 2000,
        Bandwidth = 50,
    });

    // Create Dedicated Load Balancer with the first matched flavor
    var lb = new Sbercloud.ElbLoadbalancer("lb", new()
    {
        L7FlavorId = flavors.Apply(getElbFlavorsResult => getElbFlavorsResult.Ids[0]),
    });

});
```
```go
package main

import (
	"github.com/pulumi/pulumi/sdk/v3/go/pulumi"
	"github.com/simple-container-com/pulumi-sbercloud/sdk/go/sbercloud"
)

func main() {
	pulumi.Run(func(ctx *pulumi.Context) error {
		flavors, err := sbercloud.GetElbFlavors(ctx, &sbercloud.GetElbFlavorsArgs{
			Type:           pulumi.StringRef("L7"),
			MaxConnections: pulumi.IntRef(200000),
			Cps:            pulumi.IntRef(2000),
			Bandwidth:      pulumi.IntRef(50),
		}, nil)
		if err != nil {
			return err
		}
		// Create Dedicated Load Balancer with the first matched flavor
		_, err = sbercloud.NewElbLoadbalancer(ctx, "lb", &sbercloud.ElbLoadbalancerArgs{
			L7FlavorId: pulumi.String(flavors.Ids[0]),
		})
		if err != nil {
			return err
		}
		return nil
	})
}
```
